def choose_move(observation):
    dx, dy = 0, 0
    w = observation.get('grid_width', 0)
    h = observation.get('grid_height', 0)
    x, y = observation.get('self_position', (0, 0))
    ox, oy = observation.get('opponent_position', (0, 0))
    res = observation.get('resources', [])
    obs = observation.get('obstacles', [])
    rem = observation.get('remaining_resource_count', 0)

    def inb(nx, ny):
        return 0 <= nx < w and 0 <= ny < h

    # Build a simple preference: move toward nearest resource not blocked by obstacle
    best = None
    bestd = None
    for r in res:
        rx, ry = r.get('x', 0), r.get('y', 0)
        if not inb(rx, ry):
            continue
        if (rx, ry) in [(o.get('x', -1), o.get('y', -1)) for o in obs]:
            continue
        d = abs(x - rx) + abs(y - ry)
        if bestd is None or d < bestd:
            bestd = d
            best = (rx, ry)

    if best is not None:
        dx = 0
        dy = 0
        if best[0] > x:
            dx = 1
        elif best[0] < x:
            dx = -1
        if best[1] > y:
            dy = 1
        elif best[1] < y:
            dy = -1
        if dx != 0 or dy != 0:
            return [dx, dy]

    # If no resource or blocked, try to move away from opponent if adjacent threat
    if (abs(x - ox) + abs(y - oy)) <= 1:
        if ox > x and inb(x - 1, y):
            return [-1, 0]
        if ox < x and inb(x + 1, y):
            return [1, 0]
        if oy > y and inb(x, y - 1):
            return [0, -1]
        if oy < y and inb(x, y + 1):
            return [0, 1]

    # Otherwise stay in place if nothing better
    return [0, 0]
